import React from "react";

export const Header = () => {
  return(
    <header className={'mainHeader'}>
    <nav>
      <a href="#first">Home</a>
      <a href="#seconf">About</a>
      <a href="#third">Contact</a>
    </nav>
  </header>
);
};
